<?php

declare(strict_types=1);

require_once 'db.php';
require_once 'functions.php';

function get_value(string $key): string {
  return trim($_GET[$key] ?? '');
}

function e(string $value): string {
  return htmlspecialchars($value, ENT_QUOTES, 'UTF-8');
}

$search = get_value('search');

if ($search === '') {
  $recipes = all_recipes($conn);
} else {
  $recipes = search_recipes($conn, $search);
}

$result = mysqli_query($conn, 'SELECT COUNT(*) AS total FROM recipes');
$total = (int) mysqli_fetch_assoc($result)['total'];

// AI-generated: This code was generated by ChatGPT to map category count results to the corresponding category variables.
$category_counts = category_counts($conn);

$meat_count = 0;
$seafood_count = 0;
$vegetarian_count = 0;

foreach ($category_counts as $category) {
    if ($category['name'] === 'Meat') {
      $meat_count = $category['recipe_count'];
    }

    if ($category['name'] === 'Seafood') {
      $seafood_count = $category['recipe_count'];
    }

    if ($category['name'] === 'Vegetarian') {
      $vegetarian_count = $category['recipe_count'];
    }
}
